def configure_existing_workspaces_and_language(apps, schema_editor):
    Workspace = apps.get_model("db", "Workspace")
    WorkspaceResearchSetting = apps.get_model("db", "WorkspaceResearchSetting")
    Profile = apps.get_model("db", "Profile")

    database_alias = schema_editor.connection.alias
    for workspace in Workspace.objects.using(database_alias).filter(
        slug__in=("public", "pi"),
        deleted_at__isnull=True,
    ):
        setting, _ = WorkspaceResearchSetting.objects.using(database_alias).get_or_create(
            workspace_id=workspace.id
        )
        setting.purpose = "PUBLIC_RESEARCH" if workspace.slug == "public" else "PI_PRIVATE"
        update_fields = ["purpose", "updated_at"]
        if workspace.slug == "pi":
            setting.module_enabled = False
            update_fields.append("module_enabled")
        setting.save(using=database_alias, update_fields=update_fields)
    Profile.objects.using(database_alias).exclude(language="zh-CN").update(language="zh-CN")


